	["WorldLayout"] = [[-- WorldLayout: all spatial queries the builders need, backed by the baked heightmap from the planner.
-- Nothing in this module guesses terrain: it samples the exact field the Python validator checked.
local Config = require(script.Parent.MapConfig)

local WorldLayout = {}

local HM = Config.Heightmap
local SIZE = HM.size
local RES = HM.res
local CELL = HM.cell
local WATER = HM.water
local HALF = SIZE * 0.5

local function clamp(v: number, lo: number, hi: number): number
	return math.max(lo, math.min(hi, v))
end

function WorldLayout.size(): number
	return SIZE
end

function WorldLayout.waterLevel(): number
	return WATER
end

function WorldLayout.half(): number
	return HALF
end

-- Bilinear sample of the baked heightmap. Same interpolation the planner used for validation.
function WorldLayout.heightAt(x: number, z: number): number
	local fx = clamp((x + HALF) / CELL, 0, RES - 1)
	local fz = clamp((z + HALF) / CELL, 0, RES - 1)
	local x0 = math.floor(fx)
	local z0 = math.floor(fz)
	local x1 = math.min(x0 + 1, RES - 1)
	local z1 = math.min(z0 + 1, RES - 1)
	local tx, tz = fx - x0, fz - z0
	local rowA = HM.rows[z0 + 1]
	local rowB = HM.rows[z1 + 1]
	local a = rowA[x0 + 1]
	local b = rowA[x1 + 1]
	local c = rowB[x0 + 1]
	local d = rowB[x1 + 1]
	local ab = a + (b - a) * tx
	local cd = c + (d - c) * tx
	return ab + (cd - ab) * tz
end

function WorldLayout.slopeDeg(x: number, z: number): number
	local d = math.max(CELL, 1)
	local hx = WorldLayout.heightAt(x + d, z) - WorldLayout.heightAt(x - d, z)
	local hz = WorldLayout.heightAt(x, z + d) - WorldLayout.heightAt(x, z - d)
	return math.deg( math.atan(math.sqrt(hx * hx + hz * hz) / (2 * d)) )
end

function WorldLayout.isWater(x: number, z: number, margin: number?): boolean
	return WorldLayout.heightAt(x, z) < WATER + (margin or 0.4)
end

function WorldLayout.clampToWorld(x: number, z: number, margin: number?): (number, number)
	local m = HALF - (margin or 12)
	return clamp(x, -m, m), clamp(z, -m, m)
end

local function pointSegmentDistance(px: number, pz: number, ax: number, az: number, bx: number, bz: number): number
	local dx, dz = bx - ax, bz - az
	local denom = dx * dx + dz * dz
	if denom == 0 then
		return math.sqrt((px - ax) ^ 2 + (pz - az) ^ 2)
	end
	local t = clamp(((px - ax) * dx + (pz - az) * dz) / denom, 0, 1)
	local cx, cz = ax + t * dx, az + t * dz
	return math.sqrt((px - cx) ^ 2 + (pz - cz) ^ 2)
end

function WorldLayout.pathDistance(x: number, z: number): number
	local best = math.huge
	for _, path in ipairs(Config.Paths) do
		local nodes = path.nodes
		for i = 1, #nodes - 1 do
			local a, b = nodes[i], nodes[i + 1]
			local d = pointSegmentDistance(x, z, a[1], a[2], b[1], b[2])
			if d < best then
				best = d
			end
		end
	end
	return best
end

function WorldLayout.nearestRegion(x: number, z: number)
	local best, bestDist = nil, math.huge
	for _, region in ipairs(Config.Regions) do
		local dx, dz = x - region.center[1], z - region.center[2]
		local d = math.sqrt(dx * dx + dz * dz)
		if d < bestDist then
			best, bestDist = region, d
		end
	end
	return best, bestDist
end

function WorldLayout.regionById(id: string)
	for _, region in ipairs(Config.Regions) do
		if region.id == id then
			return region
		end
	end
	return nil
end

-- Sample a polyline into evenly spaced points. Used by the path builder and by QA raycasts.
function WorldLayout.samplePath(path, spacing: number)
	local points = {}
	for i = 1, #path.nodes - 1 do
		local a, b = path.nodes[i], path.nodes[i + 1]
		local dx, dz = b[1] - a[1], b[2] - a[2]
		local segLen = math.sqrt(dx * dx + dz * dz)
		local steps = math.max(1, math.ceil(segLen / spacing))
		for s = 0, steps - 1 do
			local t = s / steps
			table.insert(points, { a[1] + dx * t, a[2] + dz * t })
		end
	end
	local last = path.nodes[#path.nodes]
	table.insert(points, { last[1], last[2] })
	return points
end

function WorldLayout.groundY(x: number, z: number): number
	return WorldLayout.heightAt(x, z)
end

return WorldLayout
]],
	["AssetLibrary"] = [[-- AssetLibrary: turns an asset recipe (or a generated mesh, when one exists) into a Model.
--
-- Priority order:
--   1. ReplicatedStorage.Idea2World_Meshes/<assetId>  -- a mesh produced by Studio's generate_mesh
--   2. the layered part recipe from the planner         -- shaped primitives, never a box stack
-- Both paths return a Model with a PrimaryPart so builders can PivotTo() it.
local Config = require(script.Parent.MapConfig)

local AssetLibrary = {}

AssetLibrary.partsCreated = 0
AssetLibrary.modelsCreated = 0
AssetLibrary.meshesUsed = 0

local SHAPES = {
	Ball = Enum.PartType.Ball,
	Cylinder = Enum.PartType.Cylinder,
	Block = Enum.PartType.Block,
}

local MATERIALS = {}
for _, name in ipairs({ "Plastic", "SmoothPlastic", "Neon", "Wood", "WoodPlanks", "Marble", "Slate",
	"Concrete", "Brick", "Cobblestone", "Rock", "Sand", "Grass", "Mud", "Ground", "Glacier", "Snow",
	"Metal", "CorrodedMetal", "Glass", "ForceField", "Fabric", "Basalt", "CrackedLava", "Water" }) do
	MATERIALS[name] = Enum.Material[name]
end

local colorCache = {}
local function parseHex(hex: string): Color3
	local cached = colorCache[hex]
	if cached then
		return cached
	end
	local r = tonumber(string.sub(hex, 2, 3), 16) or 150
	local g = tonumber(string.sub(hex, 4, 5), 16) or 150
	local b = tonumber(string.sub(hex, 6, 7), 16) or 150
	local color = Color3.fromRGB(r, g, b)
	colorCache[hex] = color
	return color
end

function AssetLibrary.resolveColor(token: string?, fallback: Color3?): Color3
	if type(token) ~= "string" then
		return fallback or Color3.fromRGB(150, 150, 150)
	end
	if string.sub(token, 1, 5) == "role:" then
		local role = string.sub(token, 6)
		local hex = Config.Palette[role] or Config.Palette.field or "#9aa4ae"
		return parseHex(hex)
	end
	if string.sub(token, 1, 1) == "#" then
		return parseHex(token)
	end
	return fallback or Color3.fromRGB(150, 150, 150)
end

local function materialFor(name: string?): Enum.Material
	if name and MATERIALS[name] then
		return MATERIALS[name]
	end
	return Enum.Material.SmoothPlastic
end

local function buildPart(spec, parent: Instance, baseCFrame: CFrame, tint: Color3?, scale: number)
	scale = scale or 1
	local shape = spec.shape
	local part: BasePart
	if shape == "Wedge" then
		part = Instance.new("WedgePart")
	elseif shape == "CornerWedge" then
		part = Instance.new("CornerWedgePart")
	else
		part = Instance.new("Part")
		part.Shape = SHAPES[shape] or Enum.PartType.Block
	end
	local sx = math.max(0.12, spec.size[1] * scale)
	local sy = math.max(0.12, spec.size[2] * scale)
	local sz = math.max(0.12, spec.size[3] * scale)
	part.Name = spec.name or "Part"
	part.Size = Vector3.new(sx, sy, sz)
	part.Anchored = true
	part.CanCollide = spec.collide ~= false
	part.CanTouch = spec.collide ~= false
	part.CastShadow = math.max(sx, sy, sz) > 3
	part.TopSurface = Enum.SurfaceType.Smooth
	part.BottomSurface = Enum.SurfaceType.Smooth
	part.Material = materialFor(spec.material)
	local color = AssetLibrary.resolveColor(spec.color, tint)
	if tint and spec.emissive then
		color = color:Lerp(tint, 0.35)
	end
	part.Color = color
	part.Transparency = spec.transparency or 0
	part.Reflectance = spec.reflectance or 0
	local offset = spec.offset or { 0, 0, 0 }
	local rot = spec.rot or { 0, 0, 0 }
	part.CFrame = baseCFrame
		* CFrame.new(offset[1] * scale, offset[2] * scale, offset[3] * scale)
		* CFrame.Angles(math.rad(rot[1] or 0), math.rad(rot[2] or 0), math.rad(rot[3] or 0))
	part.Parent = parent
	AssetLibrary.partsCreated += 1
	return part
end

local function findGeneratedMesh(assetId: string): Instance?
	local folder = game:GetService("ReplicatedStorage"):FindFirstChild("Idea2World_Meshes")
	if not folder then
		return nil
	end
	local mesh = folder:FindFirstChild(assetId)
	if not mesh then
		return nil
	end
	if not mesh:IsA("Model") and not mesh:IsA("BasePart") then
		return nil
	end
	return mesh
end

-- create(asset, options) -> Model
-- options: position (Vector3), rotation (degrees), scale (number), tint (Color3), parent (Instance)
function AssetLibrary.create(asset, options)
	options = options or {}
	local model = Instance.new("Model")
	model.Name = asset.id or asset.kind or "Asset"
	model:SetAttribute("AssetKind", asset.kind)
	model:SetAttribute("AssetId", asset.id)
	local yaw = math.rad(options.rotation or 0)
	local scale = options.scale or 1
	local origin = options.position or Vector3.new(0, 0, 0)
	local base = CFrame.new(origin) * CFrame.Angles(0, yaw, 0)

	local mesh = findGeneratedMesh(asset.id)
	if mesh then
		local clone = mesh:Clone()
		if clone:IsA("Model") then
			if not clone.PrimaryPart then
				clone.PrimaryPart = clone:FindFirstChildWhichIsA("BasePart")
			end
			clone:PivotTo(base)
			if scale ~= 1 then
				clone:ScaleTo(scale)
			end
		else
			clone.Size = clone.Size * scale
			clone.CFrame = base
		end
		clone.Parent = options.parent or workspace
		for _, descendant in ipairs(clone:GetDescendants()) do
			if descendant:IsA("BasePart") then
				descendant.Anchored = true
				if options.tint then
					descendant.Color = descendant.Color:Lerp(options.tint, 0.2)
				end
			end
		end
		clone:SetAttribute("AssetKind", asset.kind)
		clone:SetAttribute("AssetId", asset.id)
		AssetLibrary.meshesUsed += 1
		AssetLibrary.modelsCreated += 1
		return clone
	end

	local primary: BasePart? = nil
	local largest = 0
	for _, spec in ipairs(asset.parts or {}) do
		local part = buildPart(spec, model, base, options.tint, scale)
		local volume = part.Size.X * part.Size.Y * part.Size.Z
		if volume > largest then
			largest = volume
			primary = part
		end
	end
	if primary then
		model.PrimaryPart = primary
	end
	model.Parent = options.parent or workspace
	AssetLibrary.modelsCreated += 1
	return model
end

-- A cheap version for distant scatter: only the two largest parts. Used when a placement sits
-- far from the player path and the extra silhouette detail cannot be resolved anyway.
function AssetLibrary.createLowDetail(asset, options)
	local simplified = { id = asset.id, kind = asset.kind, parts = {} }
	local sorted = {}
	for _, spec in ipairs(asset.parts or {}) do
		table.insert(sorted, spec)
	end
	table.sort(sorted, function(a, b)
		return (a.size[1] * a.size[2] * a.size[3]) > (b.size[1] * b.size[2] * b.size[3])
	end)
	for i = 1, math.min(3, #sorted) do
		table.insert(simplified.parts, sorted[i])
	end
	return AssetLibrary.create(simplified, options)
end

function AssetLibrary.assetById(id: string)
	for _, asset in ipairs(Config.Assets) do
		if asset.id == id then
			return asset
		end
	end
	return nil
end

function AssetLibrary.assetsByCategory(category: string)
	local out = {}
	for _, asset in ipairs(Config.Assets) do
		if asset.category == category then
			table.insert(out, asset)
		end
	end
	return out
end

function AssetLibrary.stats()
	return {
		parts = AssetLibrary.partsCreated,
		models = AssetLibrary.modelsCreated,
		meshes = AssetLibrary.meshesUsed,
	}
end

return AssetLibrary
]],
	["TerrainBuilder"] = [[-- TerrainBuilder: writes real Roblox Terrain from the baked heightfield, then fills water bodies.
-- Terrain (not parts) is what keeps a 2000x2000 world under a sane instance count.
local Config = require(script.Parent.MapConfig)
local WorldLayout = require(script.Parent.WorldLayout)

local TerrainBuilder = {}

local TERRAIN = workspace.Terrain
local HALF = WorldLayout.half()
local WATER = WorldLayout.waterLevel()
local SIZE = WorldLayout.size()

local function materialForRegion(region): Enum.Material
	local name = region and region.ground or "Ground"
	local ok, material = pcall(function()
		return Enum.Material[name]
	end)
	if ok then
		return material
	end
	return Enum.Material.Ground
end

local function materialAt(x: number, z: number, h: number): Enum.Material
	if h < WATER + 1.6 then
		return Enum.Material.Mud
	end
	local region = WorldLayout.nearestRegion(x, z)
	if h > 96 and (region and (region.kind == "highlands" or region.kind == "canyon")) then
		return Enum.Material.Rock
	end
	return materialForRegion(region)
end

function TerrainBuilder.build(parent, progress)
	local cells = Config.TerrainCells
	local step = SIZE / cells
	local created = 0
	local started = os.clock()
	for ix = 1, cells do
		for iz = 1, cells do
			local x = -HALF + (ix - 0.5) * step
			local z = -HALF + (iz - 0.5) * step
			local h = WorldLayout.heightAt(x, z)
			local material = materialAt(x, z, h)
			-- Extend below the lowest terrain so the world has no holes at the edges.
			TERRAIN:FillBlock(CFrame.new(x, h * 0.5 - 26, z), Vector3.new(step + 1.4, h + 52, step + 1.4), material)
			created += 1
		end
		if progress then
			progress(ix / cells, ("terrain row %d/%d"):format(ix, cells))
		end
		task.wait()
	end
	local elapsed = os.clock() - started
	return { blocks = created, cells = cells, seconds = math.floor(elapsed * 10) / 10 }
end

function TerrainBuilder.fillWater(progress)
	local filled = 0
	local step = math.max(9, SIZE / 180)
	for _, region in ipairs(Config.Regions) do
		if region.water then
			local cx, cz = region.center[1], region.center[2]
			local extent = region.radius * 1.15
			local n = math.ceil(extent * 2 / step)
			for ix = 0, n do
				for iz = 0, n do
					local x = cx - extent + ix * step
					local z = cz - extent + iz * step
					local h = WorldLayout.heightAt(x, z)
					local depth = WATER - h
					if depth > 0.4 then
						TERRAIN:FillBlock(CFrame.new(x, h + depth * 0.5, z), Vector3.new(step + 1.2, depth + 0.6, step + 1.2),
							Enum.Material.Water)
						filled += 1
					end
				end
				if progress and ix % 4 == 0 then
					progress(ix / math.max(1, n), ("water body %s"):format(region.name or region.id))
				end
			end
		end
	end
	task.wait()
	return { waterCells = filled }
end

return TerrainBuilder
]],
	["BiomeBuilder"] = [[-- BiomeBuilder: ground tint plates, shore bands and snow caps.
-- Cheap (a few hundred non-colliding discs) but it is the difference between "one flat terrain
-- colour" and a world where each district reads as its own place.
local Config = require(script.Parent.MapConfig)
local WorldLayout = require(script.Parent.WorldLayout)
local AssetLibrary = require(script.Parent.AssetLibrary)

local BiomeBuilder = {}

local function disc(parent, name, x, z, y, size, color, transparency, material)
	local part = Instance.new("Part")
	part.Name = name
	part.Shape = Enum.PartType.Ball
	part.Size = Vector3.new(size, math.max(0.6, size * 0.045), size)
	part.CFrame = CFrame.new(x, y, z)
	part.Anchored = true
	part.CanCollide = false
	part.CanQuery = false
	part.CanTouch = false
	part.CastShadow = false
	part.Transparency = transparency
	part.Color = color
	part.Material = material or Enum.Material.Ground
	part.Parent = parent
	return part
end

function BiomeBuilder.build(parent, progress)
	local zones = Config.Biomes or {}
	local total = 0
	for index, zone in ipairs(zones) do
		local folder = Instance.new("Folder")
		folder.Name = ("Biome_%s"):format(zone.region)
		folder.Parent = parent
		local tint = AssetLibrary.resolveColor(zone.tint)
		local groundColor = AssetLibrary.resolveColor(zone.color)
		local material = Enum.Material.Ground
		pcall(function()
			material = Enum.Material[zone.material] or Enum.Material.Ground
		end)
		for _, patch in ipairs(zone.patches or {}) do
			local color = groundColor:Lerp(tint, zone.tint_mix or 0.35)
			disc(folder, "GroundTint", patch.x, patch.z, patch.y, patch.size, color, patch.alpha or 0.3, material)
			total += 1
		end
		-- Shore band: a lighter ring where the terrain meets water so coastlines read from a distance.
		if zone.water then
			local region = WorldLayout.regionById(zone.region)
			if region then
				local cx, cz = region.center[1], region.center[2]
				local segments = 14
				for i = 1, segments do
					local angle = (i / segments) * math.pi * 2
					local radius = region.radius * 1.02
					local x, z = cx + math.cos(angle) * radius, cz + math.sin(angle) * radius
					local h = WorldLayout.heightAt(x, z)
					if math.abs(h - WorldLayout.waterLevel()) < 6 then
						disc(folder, "Shore", x, z, h + 0.2, region.radius * 0.5,
							AssetLibrary.resolveColor("role:highlight"), 0.35, Enum.Material.Sand)
						total += 1
					end
				end
			end
		end
		-- Snow caps on the high ground of elevated districts.
		if zone.snow_cap then
			local region = WorldLayout.regionById(zone.region)
			if region then
				local cx, cz = region.center[1], region.center[2]
				local h = WorldLayout.heightAt(cx, cz)
				if h > WorldLayout.waterLevel() + 24 then
					disc(folder, "SnowCap", cx, cz, h + 0.35, region.radius * 0.9,
						Color3.fromRGB(238, 244, 250), 0.15, Enum.Material.Snow)
					total += 1
				end
			end
		end
		if progress then
			progress(index / math.max(1, #zones), ("biome %s"):format(zone.region))
		end
		if index % 3 == 0 then
			task.wait()
		end
	end
	return { patches = total }
end

return BiomeBuilder
]],
	["PathBuilder"] = [[-- PathBuilder: builds walkable route ribbons that follow the terrain, plus edge stones.
local Config = require(script.Parent.MapConfig)
local WorldLayout = require(script.Parent.WorldLayout)
local AssetLibrary = require(script.Parent.AssetLibrary)

local PathBuilder = {}

local WATER = WorldLayout.waterLevel()

local function pathColor(kind: string): Color3
	local base = AssetLibrary.resolveColor("role:highlight")
	local structure = AssetLibrary.resolveColor("role:structure")
	if kind == "main" then
		return base:Lerp(structure, 0.25)
	elseif kind == "loop" then
		return base:Lerp(structure, 0.45)
	end
	return base:Lerp(structure, 0.65)
end

function PathBuilder.build(parent, progress)
	local total = 0
	local skipped = 0
	local pathsRoot = Instance.new("Folder")
	pathsRoot.Name = "Paths"
	pathsRoot.Parent = parent
	local stoneAsset = AssetLibrary.assetById("asset_rock_boulder")
	for index, path in ipairs(Config.Paths) do
		local folder = Instance.new("Folder")
		folder.Name = ("Path_%s"):format(path.id)
		folder:SetAttribute("PathKind", path.kind)
		folder:SetAttribute("Width", path.width)
		folder.Parent = pathsRoot
		local width = path.width
		local spacing = math.max(7, width * 0.8)
		local points = WorldLayout.samplePath(path, spacing)
		local color = pathColor(path.kind)
		local material = path.kind == "main" and Enum.Material.Cobblestone or Enum.Material.Ground
		local previous = nil
		for i, point in ipairs(points) do
			local h = WorldLayout.heightAt(point[1], point[2])
			if h >= WATER - 0.3 then
				local part = Instance.new("Part")
				part.Name = ("PathTile_%03d"):format(i)
				part.Shape = Enum.PartType.Ball
				part.Size = Vector3.new(width, math.max(0.8, width * 0.09), width)
				part.CFrame = CFrame.new(point[1], h + 0.18, point[2])
					* CFrame.Angles(0, math.rad((i * 37) % 360), 0)
				part.Anchored = true
				part.CanCollide = false
				part.CanQuery = true
				part.CastShadow = false
				part.Material = material
				part.Color = color
				part.Parent = folder
				total += 1
				-- Edge stones define the route even when the path colour is close to the ground.
				if stoneAsset and previous and i % 3 == 0 then
					local dx, dz = point[1] - previous[1], point[2] - previous[2]
					local len = math.sqrt(dx * dx + dz * dz)
					if len > 0.1 then
						local nx, nz = -dz / len, dx / len
						local side = (i % 6 == 0) and 1 or -1
						local sx = point[1] + nx * (width * 0.55) * side
						local sz = point[2] + nz * (width * 0.55) * side
						AssetLibrary.createLowDetail(stoneAsset, {
							position = Vector3.new(sx, WorldLayout.heightAt(sx, sz), sz),
							rotation = (i * 53) % 360,
							scale = 0.22,
							parent = folder,
						})
					end
				end
			else
				skipped += 1
			end
			previous = point
		end
		if progress then
			progress(index / math.max(1, #Config.Paths), ("path %s"):format(path.name))
		end
		task.wait()
	end
	return { tiles = total, underwaterTiles = skipped }
end

return PathBuilder
]],
	["VegetationBuilder"] = [[-- VegetationBuilder: places the vegetation share of the placement plan, grouped per district.
-- Distant vegetation uses a reduced recipe: silhouette stays, part count drops, frame time holds.
local Config = require(script.Parent.MapConfig)
local WorldLayout = require(script.Parent.WorldLayout)
local AssetLibrary = require(script.Parent.AssetLibrary)

local VegetationBuilder = {}

local function folderFor(parent, name)
	local folder = parent:FindFirstChild(name)
	if folder then
		return folder
	end
	folder = Instance.new("Folder")
	folder.Name = name
	folder.Parent = parent
	return folder
end

function VegetationBuilder.build(parent, progress)
	local root = folderFor(parent, "Vegetation")
	local spawn = Config.Spawns[1]
	local spawnX, spawnZ = 0, 0
	if spawn then
		spawnX, spawnZ = spawn.x, spawn.z
	end
	local farDistance = WorldLayout.size() * 0.34
	local placed = 0
	local lowDetail = 0
	local regionIds = {}
	for regionId in pairs(Config.Placements) do
		table.insert(regionIds, regionId)
	end
	table.sort(regionIds)
	for index, regionId in ipairs(regionIds) do
		local regionFolder = folderFor(root, regionId)
		for _, entry in ipairs(Config.Placements[regionId]) do
			local assetId, x, z, rot, scale, color = entry[1], entry[2], entry[3], entry[4], entry[5], entry[6]
			local asset = AssetLibrary.assetById(assetId)
			if asset and asset.category == "vegetation" then
				local y = WorldLayout.heightAt(x, z)
				local distance = math.sqrt((x - spawnX) ^ 2 + (z - spawnZ) ^ 2)
				local options = {
					position = Vector3.new(x, y, z),
					rotation = rot,
					scale = scale,
					tint = color and AssetLibrary.resolveColor(color) or nil,
					parent = regionFolder,
				}
				if distance > farDistance and scale < 1.05 then
					AssetLibrary.createLowDetail(asset, options)
					lowDetail += 1
				else
					AssetLibrary.create(asset, options)
				end
				placed += 1
			end
		end
		if progress then
			progress(index / math.max(1, #regionIds), ("vegetation %s"):format(regionId))
		end
		task.wait()
	end
	return { placed = placed, lowDetail = lowDetail }
end

return VegetationBuilder
]],
	["AssetPlacement"] = [[-- AssetPlacement: rocks, props, creatures and the decorative ring around each landmark.
local Config = require(script.Parent.MapConfig)
local WorldLayout = require(script.Parent.WorldLayout)
local AssetLibrary = require(script.Parent.AssetLibrary)

local AssetPlacement = {}

local function folderFor(parent, name)
	local folder = parent:FindFirstChild(name)
	if folder then
		return folder
	end
	folder = Instance.new("Folder")
	folder.Name = name
	folder.Parent = parent
	return folder
end

function AssetPlacement.build(parent, progress)
	local root = folderFor(parent, "Details")
	local placed = 0
	local regions = {}
	for regionId in pairs(Config.Placements) do
		table.insert(regions, regionId)
	end
	table.sort(regions)
	for index, regionId in ipairs(regions) do
		local regionFolder = folderFor(root, regionId)
		for _, entry in ipairs(Config.Placements[regionId]) do
			local assetId, x, z, rot, scale, color = entry[1], entry[2], entry[3], entry[4], entry[5], entry[6]
			local asset = AssetLibrary.assetById(assetId)
			if asset and (asset.category == "prop" or asset.category == "rock" or asset.category == "creature") then
				local y = WorldLayout.heightAt(x, z)
				AssetLibrary.create(asset, {
					position = Vector3.new(x, y, z),
					rotation = rot,
					scale = scale,
					tint = color and AssetLibrary.resolveColor(color) or nil,
					parent = regionFolder,
				})
				placed += 1
			end
		end
		if progress then
			progress(index / math.max(1, #regions), ("props %s"):format(regionId))
		end
	end
	-- Landmark framing: lamps and theme props around each POI pad edge.
	local decorFolder = folderFor(root, "LandmarkDressing")
	-- PoiDecor rows are {assetId, poiId, x, z, rotationDeg, scale, tint}
	for _, entry in ipairs(Config.PoiDecor or {}) do
		local assetId, x, z, rot, scale, color = entry[1], entry[3], entry[4], entry[5], entry[6], entry[7]
		local asset = AssetLibrary.assetById(assetId)
		if asset then
			local y = WorldLayout.heightAt(x, z)
			AssetLibrary.create(asset, {
				position = Vector3.new(x, y, z),
				rotation = rot,
				scale = scale,
				tint = color and AssetLibrary.resolveColor(color) or nil,
				parent = decorFolder,
			})
			placed += 1
		end
	end
	task.wait()
	return { placed = placed }
end

return AssetPlacement
]],
	["BuildingBuilder"] = [[-- BuildingBuilder: raises every landmark from its layered recipe and tags it for interaction.
-- Structures are Models with a PrimaryPart, a BillboardGui name tag and an interaction anchor.
local Config = require(script.Parent.MapConfig)
local WorldLayout = require(script.Parent.WorldLayout)
local AssetLibrary = require(script.Parent.AssetLibrary)

local BuildingBuilder = {}

local function makeLabel(adornee: BasePart, text: string, color: Color3)
	local billboard = Instance.new("BillboardGui")
	billboard.Name = "LandmarkLabel"
	billboard.Size = UDim2.fromScale(18, 3.2)
	billboard.StudsOffset = Vector3.new(0, 8, 0)
	billboard.AlwaysOnTop = false
	billboard.MaxDistance = 620
	billboard.LightInfluence = 0
	billboard.Adornee = adornee
	local label = Instance.new("TextLabel")
	label.Size = UDim2.fromScale(1, 1)
	label.BackgroundTransparency = 0.25
	label.BackgroundColor3 = Color3.fromRGB(14, 18, 24)
	label.TextColor3 = color
	label.TextStrokeTransparency = 0.6
	label.Font = Enum.Font.GothamBold
	label.TextScaled = true
	label.Text = text
	label.Parent = billboard
	billboard.Parent = adornee
	return billboard
end

local function interactionAnchor(model: Model, poi): BasePart?
	local primary = model.PrimaryPart
	if not primary then
		return nil
	end
	local anchor = Instance.new("Part")
	anchor.Name = "InteractionAnchor"
	anchor.Size = Vector3.new(10, 8, 10)
	anchor.CFrame = primary.CFrame * CFrame.new(0, 3, 0)
	anchor.Anchored = true
	anchor.CanCollide = false
	anchor.CanQuery = false
	anchor.Transparency = 1
	anchor:SetAttribute("Interaction", poi.interaction or "landmark")
	anchor:SetAttribute("PoiName", poi.name)
	anchor:SetAttribute("PoiKind", poi.kind)
	anchor.Parent = model
	return anchor
end

function BuildingBuilder.build(parent, progress)
	local root = Instance.new("Folder")
	root.Name = "Landmarks"
	root.Parent = parent
	local built = 0
	local skipped = 0
	local accent = AssetLibrary.resolveColor("role:accent")
	for index, poi in ipairs(Config.Pois) do
		local asset = AssetLibrary.assetById("asset_" .. poi.kind)
		if asset then
			local x, z = poi.x, poi.z
			local y = WorldLayout.heightAt(x, z)
			if y < WorldLayout.waterLevel() - 1.5 and poi.kind ~= "lake" and poi.kind ~= "bridge" and poi.kind ~= "dock" then
				-- Never bury a structure under a lake; lift it onto the shore instead.
				skipped += 1
			else
				local regionFolder = root:FindFirstChild(poi.region)
				if not regionFolder then
					regionFolder = Instance.new("Folder")
					regionFolder.Name = poi.region
					regionFolder.Parent = root
				end
				local model = AssetLibrary.create(asset, {
					position = Vector3.new(x, y, z),
					rotation = poi.rotation or 0,
					scale = poi.scale or 1,
					parent = regionFolder,
				})
				model.Name = poi.name
				model:SetAttribute("PoiKind", poi.kind)
				model:SetAttribute("PoiId", poi.id)
				model:SetAttribute("Interaction", poi.interaction or "landmark")
				if model.PrimaryPart then
					makeLabel(model.PrimaryPart, poi.name, accent)
				end
				interactionAnchor(model, poi)
				built += 1
			end
		end
		if progress then
			progress(index / math.max(1, #Config.Pois), ("landmark %s"):format(poi.name))
		end
		task.wait()
	end
	return { built = built, skipped = skipped }
end

return BuildingBuilder
]],
	["LightingController"] = [[-- LightingController: applies the art-direction lighting rig and post effects.
local Config = require(script.Parent.MapConfig)
local AssetLibrary = require(script.Parent.AssetLibrary)

local LightingController = {}

function LightingController.build(parent, progress)
	local Lighting = game:GetService("Lighting")
	local settings = Config.Lighting or {}
	Lighting.ClockTime = settings.clockTime or 15
	Lighting.Brightness = settings.brightness or 2
	Lighting.EnvironmentDiffuseScale = 0.4
	Lighting.EnvironmentSpecularScale = 0.4
	Lighting.GlobalShadows = true
	Lighting.ShadowSoftness = 0.35
	local ambient = settings.ambient or { 96, 104, 120 }
	Lighting.Ambient = Color3.fromRGB(ambient[1], ambient[2], ambient[3])
	Lighting.OutdoorAmbient = Color3.fromRGB(ambient[1] + 24, ambient[2] + 24, ambient[3] + 24)
	Lighting.ExposureCompensation = settings.exposure or 0.1
	pcall(function()
		Lighting.Technology = Enum.Technology.Future
	end)

	local function ensure(className: string, name: string)
		local existing = Lighting:FindFirstChild(name)
		if existing then
			return existing
		end
		local instance = Instance.new(className)
		instance.Name = name
		instance.Parent = Lighting
		return instance
	end

	local bloom = ensure("BloomEffect", "Idea2World_Bloom")
	bloom.Intensity = 0.35
	bloom.Size = 24
	bloom.Threshold = 1.05

	local colorCorrection = ensure("ColorCorrectionEffect", "Idea2World_ColorGrade")
	colorCorrection.Saturation = 0.06
	colorCorrection.Contrast = 0.08
	colorCorrection.Brightness = 0.01
	colorCorrection.TintColor = AssetLibrary.resolveColor("role:highlight"):Lerp(Color3.new(1, 1, 1), 0.82)

	local sunRays = ensure("SunRaysEffect", "Idea2World_SunRays")
	sunRays.Intensity = 0.08
	sunRays.Spread = 0.55

	if progress then
		progress(1, "lighting")
	end
	return { clockTime = Lighting.ClockTime, technology = "Future" }
end

return LightingController
]],
	["AtmosphereController"] = [[-- AtmosphereController: distance haze and colour that matches the art direction.
local Config = require(script.Parent.MapConfig)
local AssetLibrary = require(script.Parent.AssetLibrary)

local AtmosphereController = {}

function AtmosphereController.build(parent, progress)
