	["VFXController"] = [[-- VFXController: budgeted ambient particle emitters and landmark accent lights.
-- Every emitter is anchored, non-colliding and rate-limited by the planner's VFX budget, so a dense
-- art direction cannot silently destroy frame time.
local Config = require(script.Parent.MapConfig)
local WorldLayout = require(script.Parent.WorldLayout)
local AssetLibrary = require(script.Parent.AssetLibrary)

local VFXController = {}

local EMITTER_TEXTURE = "rbxasset://textures/particles/sparkles_main.dds"

local function anchorPart(parent: Instance, name: string, position: Vector3): Part
	local part = Instance.new("Part")
	part.Name = name
	part.Size = Vector3.new(2, 2, 2)
	part.Transparency = 1
	part.Anchored = true
	part.CanCollide = false
	part.CanQuery = false
	part.CastShadow = false
	part.CFrame = CFrame.new(position)
	part.Parent = parent
	return part
end

function VFXController.build(parent, progress)
	local root = Instance.new("Folder")
	root.Name = "VFX"
	root.Parent = parent
	local budget = Config.Budget or {}
	local maxEmitters = budget.maxParticleEmitters or 36
	local accent = AssetLibrary.resolveColor("role:accent")
	local emitters = 0

	for _, emitter in ipairs(Config.AmbientVfx or {}) do
		if emitters >= maxEmitters then
			break
		end
		local holder = anchorPart(root, ("Ambient_%s"):format(emitter.id), Vector3.new(emitter.x, emitter.y, emitter.z))
		local particles = Instance.new("ParticleEmitter")
		particles.Name = "AmbientParticles"
		particles.Texture = EMITTER_TEXTURE
		particles.Rate = emitter.rate or 12
		particles.Lifetime = NumberRange.new(2.5, 5.5)
		particles.Speed = NumberRange.new(0.6, 2.2)
		particles.Size = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.8),
			NumberSequenceKeypoint.new(1, 0.05),
		})
		particles.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.85),
			NumberSequenceKeypoint.new(0.25, 0.35),
			NumberSequenceKeypoint.new(1, 1),
		})
		particles.Color = ColorSequence.new(AssetLibrary.resolveColor(emitter.color):Lerp(accent, 0.4))
		particles.LightEmission = 0.6
		particles.SpreadAngle = Vector2.new(65, 65)
		particles.EmissionDirection = Enum.NormalId.Top
		particles.Parent = holder
		emitters += 1
	end

	-- Landmark accent light: one PointLight per focal POI, never per prop.
	local lightFolder = Instance.new("Folder")
	lightFolder.Name = "LandmarkLights"
	lightFolder.Parent = root
	for _, poi in ipairs(Config.Pois) do
		if emitters >= maxEmitters then
			break
		end
		if poi.role == "focal" then
			local y = WorldLayout.heightAt(poi.x, poi.z) + 18
			local holder = anchorPart(lightFolder, ("Light_%s"):format(poi.id), Vector3.new(poi.x, y, poi.z))
			local light = Instance.new("PointLight")
			light.Brightness = 1.6
			light.Range = 60
			light.Color = accent
			light.Shadows = false
			light.Parent = holder
		end
	end

	if progress then
		progress(1, ("vfx emitters %d"):format(emitters))
	end
	return { emitters = emitters }
end

return VFXController
]],
	["SoundscapeController"] = [[-- SoundscapeController: sets up the audible layer without pretending we own audio assets.
-- Roblox audio must be licensed and uploaded; the planner emits slots, not fabricated ids.
local Config = require(script.Parent.MapConfig)

local SoundscapeController = {}

function SoundscapeController.build(parent, progress)
	local SoundService = game:GetService("SoundService")
	local group = SoundService:FindFirstChild("Idea2WorldSoundscape")
	if not group then
		group = Instance.new("SoundGroup")
		group.Name = "Idea2WorldSoundscape"
		group.Volume = 0.55
		group.Parent = SoundService
	end
	local spec = Config.Soundscape or {}
	local folder = SoundService:FindFirstChild("Idea2World_Ambience")
	if folder then
		folder:Destroy()
	end
	folder = Instance.new("Folder")
	folder.Name = "Idea2World_Ambience"
	folder.Parent = SoundService

	local created = 0
	local missingSources = 0
	for _, slot in ipairs(spec.slots or {}) do
		if slot.soundId and slot.soundId ~= "" then
			local sound = Instance.new("Sound")
			sound.Name = slot.id
			sound.SoundId = slot.soundId
			sound.Volume = slot.volume or 0.4
			sound.Looped = true
			sound.SoundGroup = group
			sound.Parent = folder
			sound:Play()
			created += 1
		else
			missingSources += 1
		end
	end
	if progress then
		progress(1, ("sound slots %d"):format(#(spec.slots or {})))
	end
	return { playing = created, awaitingApprovedAudio = missingSources,
		note = "Add licensed audio ids in MapConfig.Soundscape.slots[].soundId" }
end

return SoundscapeController
]],
	["SpawnSetup"] = [[-- SpawnSetup: a single, flat, readable spawn with a landmark-visible facing direction.
local Config = require(script.Parent.MapConfig)
local WorldLayout = require(script.Parent.WorldLayout)
local AssetLibrary = require(script.Parent.AssetLibrary)

local SpawnSetup = {}

function SpawnSetup.build(parent, progress)
	local folder = Instance.new("Folder")
	folder.Name = "Spawns"
	folder.Parent = parent
	local spawns = {}
	for index, spec in ipairs(Config.Spawns) do
		local y = WorldLayout.heightAt(spec.x, spec.z) + 3.2
		local pad = Instance.new("Part")
		pad.Name = ("SpawnPad_%d"):format(index)
		pad.Shape = Enum.PartType.Cylinder
		pad.Size = Vector3.new(1.2, (spec.radius or 12) * 2, (spec.radius or 12) * 2)
		pad.CFrame = CFrame.new(spec.x, y - 0.8, spec.z) * CFrame.Angles(0, 0, math.rad(90))
		pad.Anchored = true
		pad.CanCollide = true
		pad.Material = Enum.Material.Neon
		pad.Color = AssetLibrary.resolveColor("role:accent")
		pad.Transparency = 0.35
		pad.Parent = folder

		local spawn = Instance.new("SpawnLocation")
		spawn.Name = spec.name or ("Spawn_%d"):format(index)
		spawn.Size = Vector3.new(10, 1, 10)
		spawn.CFrame = CFrame.new(spec.x, y, spec.z) * CFrame.Angles(0, math.rad(spec.facing or 0), 0)
		spawn.Anchored = true
		spawn.Neutral = true
		spawn.Duration = 0
		spawn.Transparency = 1
		spawn.CanCollide = false
		spawn.Parent = folder
		spawn:SetAttribute("SpawnId", spec.id)
		table.insert(spawns, spawn)
		workspace:SetAttribute("Idea2WorldSpawnX", spec.x)
		workspace:SetAttribute("Idea2WorldSpawnZ", spec.z)
	end
	if progress then
		progress(1, ("spawns %d"):format(#spawns))
	end
	return { count = #spawns }
end

return SpawnSetup
]],
	["InteractionSetup"] = [[-- InteractionSetup: makes landmarks usable -- prompts, labels and district name plates.
-- This is scaffolding for gameplay, not gameplay itself: hooks are exposed by name so a game
-- system can bind to them without touching generated geometry.
local Config = require(script.Parent.MapConfig)
local WorldLayout = require(script.Parent.WorldLayout)
local AssetLibrary = require(script.Parent.AssetLibrary)

local InteractionSetup = {}

local ACTIONS = {
	viewpoint = { text = "Survey", hold = 0.6, key = "E" },
	shop = { text = "Browse", hold = 0.2, key = "E" },
	social_hub = { text = "Enter", hold = 0.2, key = "E" },
	teleport = { text = "Travel", hold = 1.0, key = "E" },
	challenge = { text = "Challenge", hold = 0.4, key = "E" },
	collect = { text = "Collect", hold = 0.3, key = "E" },
	discovery = { text = "Explore", hold = 0.3, key = "E" },
	gate = { text = "Open", hold = 0.4, key = "E" },
	travel = { text = "Depart", hold = 0.3, key = "E" },
	landmark = { text = "Read", hold = 0.2, key = "E" },
}

function InteractionSetup.build(parent, progress)
	local prompts = 0
	local landmarksFolder = parent:FindFirstChild("Landmarks")
	if landmarksFolder then
		for _, model in ipairs(landmarksFolder:GetDescendants()) do
			if model:IsA("BasePart") and model:GetAttribute("Interaction") then
				local kind = model:GetAttribute("Interaction") or "landmark"
				local action = ACTIONS[kind] or ACTIONS.landmark
				local prompt = Instance.new("ProximityPrompt")
				prompt.Name = "Idea2WorldPrompt"
				prompt.ActionText = action.text
				prompt.ObjectText = model:GetAttribute("PoiName") or kind
				prompt.HoldDuration = action.hold
				prompt.KeyboardKeyCode = Enum.KeyCode.E
				prompt.MaxActivationDistance = 14
				prompt.RequiresLineOfSight = false
				prompt.Parent = model
				prompt.Triggered:Connect(function(player)
					print(("[Idea2World] %s interacted with %s"):format(player.Name, prompt.ObjectText))
				end)
				prompts += 1
			end
		end
	end

	-- District name plates: readable from the route, so players always know where they are.
	local plates = Instance.new("Folder")
	plates.Name = "DistrictPlates"
	plates.Parent = parent
	for _, region in ipairs(Config.Regions) do
		local x, z = region.center[1], region.center[2]
		local y = WorldLayout.heightAt(x, z) + 26
		local holder = Instance.new("Part")
		holder.Name = ("DistrictPlate_%s"):format(region.id)
		holder.Size = Vector3.new(1, 1, 1)
		holder.Transparency = 1
		holder.Anchored = true
		holder.CanCollide = false
		holder.CanQuery = false
		holder.CFrame = CFrame.new(x, y, z)
		holder.Parent = plates
		local billboard = Instance.new("BillboardGui")
		billboard.Size = UDim2.fromScale(20, 3)
		billboard.MaxDistance = 420
		billboard.LightInfluence = 0
		billboard.Adornee = holder
		local label = Instance.new("TextLabel")
		label.Size = UDim2.fromScale(1, 1)
		label.BackgroundTransparency = 1
		label.Font = Enum.Font.GothamMedium
		label.TextScaled = true
		label.TextColor3 = AssetLibrary.resolveColor("role:highlight")
		label.TextStrokeTransparency = 0.45
		label.Text = region.name
		label.Parent = billboard
		billboard.Parent = holder
	end

	if progress then
		progress(1, ("interaction prompts %d"):format(prompts))
	end
	return { prompts = prompts, plates = #Config.Regions }
end

return InteractionSetup
]],
	["MapValidator"] = [[-- MapValidator: post-build structural checks inside the real Studio session.
-- Python already validated the plan; this validates what actually got created.
local Config = require(script.Parent.MapConfig)
local WorldLayout = require(script.Parent.WorldLayout)

local MapValidator = {}

local function countDescendants(root: Instance): (number, number)
	local parts, models = 0, 0
	for _, descendant in ipairs(root:GetDescendants()) do
		if descendant:IsA("BasePart") then
			parts += 1
		elseif descendant:IsA("Model") then
			models += 1
		end
	end
	return parts, models
end

function MapValidator.validate(root)
	local checks = {}
	local function add(name, ok, detail)
		table.insert(checks, { name = name, ok = ok, detail = detail })
	end

	local parts, models = countDescendants(root)
	local budget = Config.Budget or {}
	add("instance_budget", parts <= (budget.maxInstances or 14000),
		("parts %d / limit %d"):format(parts, budget.maxInstances or 14000))

	local landmarks = root:FindFirstChild("Landmarks")
	local missing = {}
	local found = 0
	if landmarks then
		for _, poi in ipairs(Config.Pois) do
			local match = nil
			for _, model in ipairs(landmarks:GetDescendants()) do
				if model:IsA("Model") and model:GetAttribute("PoiId") == poi.id then
					match = model
					break
				end
			end
			if match then
				found += 1
			else
				table.insert(missing, poi.name)
			end
		end
	end
	add("landmark_coverage", #missing == 0,
		#missing == 0 and ("%d/%d landmarks built"):format(found, #Config.Pois)
			or ("missing: " .. table.concat(missing, ", ")))

	local spawnLocation = nil
	for _, descendant in ipairs(workspace:GetDescendants()) do
		if descendant:IsA("SpawnLocation") and descendant:GetAttribute("SpawnId") then
			spawnLocation = descendant
			break
		end
	end
	add("spawn_present", spawnLocation ~= nil, spawnLocation and "spawn located" or "no SpawnLocation found")

	-- Floating structure check: sample landmark primary parts and measure the drop to terrain.
	local floating = {}
	if landmarks then
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Include
		params.FilterDescendantsInstances = { workspace.Terrain }
		for _, model in ipairs(landmarks:GetDescendants()) do
			if model:IsA("Model") and model.PrimaryPart and model:GetAttribute("PoiKind") then
				local kind = model:GetAttribute("PoiKind")
				if kind ~= "bridge" and kind ~= "dock" and kind ~= "portal" and kind ~= "observatory" then
					local origin = model.PrimaryPart.Position
					local result = workspace:Raycast(origin, Vector3.new(0, -120, 0), params)
					if result and result.Distance > 40 then
						table.insert(floating, model.Name)
					end
				end
			end
		end
	end
	add("no_floating_landmarks", #floating == 0,
		#floating == 0 and "all sampled landmarks sit on terrain"
			or ("floating: " .. table.concat(floating, ", ")))

	local emitters = 0
	for _, descendant in ipairs(root:GetDescendants()) do
		if descendant:IsA("ParticleEmitter") then
			emitters += 1
		end
	end
	add("vfx_budget", emitters <= (budget.maxParticleEmitters or 36),
		("emitters %d / limit %d"):format(emitters, budget.maxParticleEmitters or 36))

	local paths = root:FindFirstChild("Paths")
	local pathParts = 0
	if paths then
		pathParts = #paths:GetDescendants()
	end
	add("routes_built", pathParts > 0, ("%d route objects"):format(pathParts))

	if spawnLocation then
		local groundY = WorldLayout.heightAt(spawnLocation.Position.X, spawnLocation.Position.Z)
		add("spawn_height", math.abs(spawnLocation.Position.Y - groundY) < 24,
			("spawn y %.1f vs ground %.1f"):format(spawnLocation.Position.Y, groundY))
	end

	local passed = true
	local failures = {}
	for _, check in ipairs(checks) do
		if not check.ok then
			passed = false
			table.insert(failures, check.name)
		end
	end
	return {
		passed = passed,
		checks = checks,
		failures = failures,
		stats = { parts = parts, models = models, emitters = emitters },
	}
end

return MapValidator
]],
	["MapBootstrap"] = [[-- MapBootstrap: staged, idempotent build of the whole world.
--
-- Use it from a Script (MapBootstrap.server.lua) or from Studio's command bar via the MCP tool
-- `execute_luau`, which requires this ModuleScript and calls Build(). Rebuilding never duplicates
-- objects: the previous world is archived to ServerStorage first, and can be restored by hand.
local Config = require(script.Parent.MapConfig)
local WorldLayout = require(script.Parent.WorldLayout)
local TerrainBuilder = require(script.Parent.TerrainBuilder)
local BiomeBuilder = require(script.Parent.BiomeBuilder)
local PathBuilder = require(script.Parent.PathBuilder)
local VegetationBuilder = require(script.Parent.VegetationBuilder)
local AssetPlacement = require(script.Parent.AssetPlacement)
local BuildingBuilder = require(script.Parent.BuildingBuilder)
local LightingController = require(script.Parent.LightingController)
local AtmosphereController = require(script.Parent.AtmosphereController)
local VFXController = require(script.Parent.VFXController)
local SoundscapeController = require(script.Parent.SoundscapeController)
local SpawnSetup = require(script.Parent.SpawnSetup)
local InteractionSetup = require(script.Parent.InteractionSetup)
local MapValidator = require(script.Parent.MapValidator)
local AssetLibrary = require(script.Parent.AssetLibrary)

local MapBootstrap = {}

local ROOT_NAME = "Idea2World_Generated"
local BACKUP_FOLDER = "Idea2World_Backups"

local function nowStamp(): string
	return os.date("!%Y%m%d-%H%M%S")
end

local function archivePrevious()
	local previous = workspace:FindFirstChild(ROOT_NAME)
	if not previous then
		return nil
	end
	local storage = game:GetService("ServerStorage")
	local backups = storage:FindFirstChild(BACKUP_FOLDER)
	if not backups then
		backups = Instance.new("Folder")
		backups.Name = BACKUP_FOLDER
		backups.Parent = storage
	end
	local archived = Instance.new("Folder")
	archived.Name = ("%s_%s"):format(ROOT_NAME, nowStamp())
	for _, child in ipairs(previous:GetChildren()) do
		child.Parent = archived
	end
	archived.Parent = backups
	previous:Destroy()
	-- Keep the three most recent archives so a bad build is always recoverable.
	local archives = {}
	for _, child in ipairs(backups:GetChildren()) do
		table.insert(archives, child)
	end
	table.sort(archives, function(a, b)
		return a.Name > b.Name
	end)
	for index = 4, #archives do
		archives[index]:Destroy()
	end
	return archived.Name
end

function MapBootstrap.build(options)
	options = options or {}
	local started = os.clock()
	-- Archive the previous world BEFORE creating the new root, otherwise the archive would
	-- swallow (and destroy) the folder we are about to build into.
	local archived = archivePrevious()
	local root = Instance.new("Folder")
	root.Name = ROOT_NAME
	root.Parent = workspace
	root:SetAttribute("BuildStage", "starting")
	root:SetAttribute("BuildProgress", 0)
	root:SetAttribute("WorldTitle", Config.Title)
	root:SetAttribute("Idea2WorldSchema", 6)

	local report = {
		title = Config.Title,
		style = Config.Style,
		theme = Config.Theme,
		stages = {},
		archivedPrevious = archived,
		startedAt = DateTime.now():ToIsoDate(),
	}

	local stageIndex = 0
	local stageCount = 11
	local function progress(label)
		return function(fraction, detail)
			local overall = (stageIndex + math.clamp(fraction or 0, 0, 1)) / stageCount
			root:SetAttribute("BuildProgress", math.floor(overall * 100))
			root:SetAttribute("BuildStage", label)
			if options.verbose and detail then
				print(("[Idea2World] %s: %s"):format(label, detail))
			end
		end
	end

	local function runStage(name, fn)
		stageIndex += 1
		local stageStarted = os.clock()
		root:SetAttribute("BuildStage", name)
		local ok, result = pcall(fn, progress(name))
		if not ok then
			print(("[Idea2World] stage '%s' failed: %s"):format(name, tostring(result)))
			table.insert(report.stages, { name = name, ok = false, error = tostring(result) })
			return false
		end
		table.insert(report.stages, {
			name = name,
			ok = true,
			seconds = math.floor((os.clock() - stageStarted) * 100) / 100,
			result = result,
		})
		task.wait()
		return true
	end

	runStage("lighting", function(p) return LightingController.build(root, p) end)
	runStage("atmosphere", function(p) return AtmosphereController.build(root, p) end)
	runStage("terrain", function(p) return TerrainBuilder.build(root, p) end)
	runStage("water", function(p) return TerrainBuilder.fillWater(p) end)
	runStage("biomes", function(p) return BiomeBuilder.build(root, p) end)
	runStage("paths", function(p) return PathBuilder.build(root, p) end)
	runStage("landmarks", function(p) return BuildingBuilder.build(root, p) end)
	runStage("vegetation", function(p) return VegetationBuilder.build(root, p) end)
	runStage("details", function(p) return AssetPlacement.build(root, p) end)
	runStage("vfx", function(p) return VFXController.build(root, p) end)
	runStage("spawns", function(p) return SpawnSetup.build(root, p) end)
	runStage("interaction", function(p) return InteractionSetup.build(root, p) end)
	runStage("soundscape", function(p) return SoundscapeController.build(root, p) end)

	local validation = MapValidator.validate(root)
	report.validation = validation

	local stats = AssetLibrary.stats()
	report.stats = {
		partsCreated = stats.parts,
		modelsCreated = stats.models,
		generatedMeshesUsed = stats.meshes,
		terrainCells = Config.TerrainCells,
		pois = #Config.Pois,
		paths = #Config.Paths,
		regions = #Config.Regions,
		placements = Config.PlacementCount,
		seconds = math.floor((os.clock() - started) * 10) / 10,
	}
	report.passed = validation.passed

	root:SetAttribute("BuildProgress", 100)
	root:SetAttribute("BuildPassed", validation.passed)
	root:SetAttribute("BuildSeconds", report.stats.seconds)

	print(("[Idea2World] built '%s' in %.1fs | %d parts, %d models, %d landmarks, %d placements | validation %s")
		:format(Config.Title, report.stats.seconds, stats.parts, stats.models, #Config.Pois,
			Config.PlacementCount, validation.passed and "PASSED" or "FAILED"))
	for _, failure in ipairs(validation.failures or {}) do
		print(("[Idea2World] validation issue: %s"):format(failure))
	end
	return report
end

function MapBootstrap.clear()
	local existing = workspace:FindFirstChild(ROOT_NAME)
	if existing then
		existing:Destroy()
	end
	return true
end

function MapBootstrap.validate()
	local existing = workspace:FindFirstChild(ROOT_NAME)
	if not existing then
		return { passed = false, failures = { "world_not_built" }, checks = {} }
	end
	return MapValidator.validate(existing)
end

function MapBootstrap.info()
	return {
		title = Config.Title,
		idea = Config.Idea,
		genre = Config.Genre,
		style = Config.Style,
		regions = #Config.Regions,
		pois = #Config.Pois,
		placements = Config.PlacementCount,
		size = WorldLayout.size(),
	}
end

return MapBootstrap
]],
	["MapBootstrap.server"] = [[-- MapBootstrap.server.lua
-- Runs the generated build when the place is played (ServerScriptService).
-- For an Edit-mode build without pressing Play, use CommandBar_Install.lua or the Idea2World
-- Studio bridge, which call MapBootstrap.build() directly.
local MapBootstrap = require(script.Parent:WaitForChild("MapBootstrap"))

local report = MapBootstrap.build({ verbose = false })

if report.passed then
	print(("[Idea2World] '%s' ready — %d landmarks, %d placements, %.1fs")
		:format(report.title, report.stats.pois, report.stats.placements, report.stats.seconds))
else
	warn(("[Idea2World] '%s' built with validation issues: %s")
		:format(report.title, table.concat(report.validation.failures or {}, ", ")))
end

-- Expose a small API for live debugging from the command bar while the game runs.
_G.Idea2World = {
	Build = MapBootstrap.build,
	Validate = MapBootstrap.validate,
	Clear = MapBootstrap.clear,
	Info = MapBootstrap.info,
}
]],
}

local ServerScriptService = game:GetService("ServerScriptService")
local container = ServerScriptService:FindFirstChild("Idea2World_Generated_Map")
if container then
	container:Destroy()
end
container = Instance.new("Folder")
container.Name = "Idea2World_Generated_Map"
container.Parent = ServerScriptService
for name, source in pairs(Sources) do
	local module = Instance.new("ModuleScript")
	module.Name = name
	module.Source = source
	module.Parent = container
end
local bootstrap = require(container:FindFirstChild("MapBootstrap"))
local report = bootstrap.build({ verbose = true })
print(("[Idea2World] build %s"):format(report.passed and "PASSED" or "FAILED"))
return report